mapper.select:
select t.section_id,t.section_id sectionId,t.pa_id,t.pa_id paId,t.community_id,t.community_id
communityId,t.section_num,t.section_num sectionNum,t.section_name,t.section_name sectionName,t.remark,t.status_cd,t.status_cd
statusCd,pa.num paName
from parking_area_section t
left join parking_area pa on t.pa_id = pa.pa_id and pa.status_cd = '0'
where 1 =1

    and t.section_id= #{sectionId}


    and t.pa_id= #{paId}


    and t.community_id= #{communityId}


    and t.section_num= #{sectionNum}


    and t.section_name= #{sectionName}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update parking_area_section t set t.status_cd = #{statusCd}

    , t.pa_id= #{paId}


    , t.section_num= #{sectionNum}


    , t.section_name= #{sectionName}


    , t.remark= #{remark}


    , t.community_id= #{communityId}

where 1=1

    and t.section_id= #{sectionId}

